import{_ as a,o as r,c as e,ag as o}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"查看和整理数据点","description":"查找数据点，查看来源与开发态当前值，复制路径、管理标签，并谨慎清理失效项。","frontmatter":{"title":"查看和整理数据点","description":"查找数据点，查看来源与开发态当前值，复制路径、管理标签，并谨慎清理失效项。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/datapoints.md","filePath":"zh/使用指南/查看和整理数据点.md"}'),n={name:"zh/guide/datapoints.md"};function d(i,t,s,l,h,p){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="查看和整理数据点" tabindex="-1">查看和整理数据点 <a class="header-anchor" href="#查看和整理数据点" aria-label="Permalink to &quot;查看和整理数据点&quot;">​</a></h1><p>数据点由查询、工业变量、计算输出等配置生成。本页从已有数据点开始，说明怎样查找、检查和整理；不是直接向设备写数据的教程。</p><p>使用有工程权限的组织账号，从“工程管理”打开目标工程的 <strong>“数据中心”</strong>，选择 <strong>“数据点”</strong>。</p><h2 id="_1-找到要看的数据点" tabindex="-1">1. 找到要看的数据点 <a class="header-anchor" href="#_1-找到要看的数据点" aria-label="Permalink to &quot;1. 找到要看的数据点&quot;">​</a></h2><p>可按路径或名称搜索，结合状态、来源、标签和排序条件缩小范围。页面还可筛选配置是否有 AI 参与记录；这个标记不是数据质量或审核结论。</p><p>找不到时，先核对工程、筛选、页码和对应来源是否已经生成数据点，再点击 <strong>“刷新数据点”</strong>。只看到当前页，不表示工程只有这些点。</p><p>列表中的名称便于辨认，路径用于明确引用，来源说明它由哪项配置产生。“位置”是目录归属提示，不要把它当成另一条数据点路径。</p><h2 id="_2-查看详情与来源" tabindex="-1">2. 查看详情与来源 <a class="header-anchor" href="#_2-查看详情与来源" aria-label="Permalink to &quot;2. 查看详情与来源&quot;">​</a></h2><ol><li>在目标行点击 <strong>“查看详情”</strong>。</li><li>核对名称、路径、数据类型、单位和来源。</li><li>需要调整原始查询、变量或计算配置时，使用来源相关入口，先核对跳转后的对象。</li></ol><p>需要引用时使用 <strong>“复制路径”</strong>，粘贴后确认完整路径。路径不是免登录访问地址，也不会给其他账号自动授权。</p><p>详情中的引用、历史存储和报警信息分别反映对应配置。某个图标不可用时先看提示，不通过更换账号或清理数据点绕过限制。</p><h2 id="_3-怎样理解-开发态当前值" tabindex="-1">3. 怎样理解“开发态当前值” <a class="header-anchor" href="#_3-怎样理解-开发态当前值" aria-label="Permalink to &quot;3. 怎样理解“开发态当前值”&quot;">​</a></h2><p>详情中的 **“开发态当前值”**用于开发和预览。核对时把值、质量、值来源、观测时间与源时间一起看，不能只凭一个数字判断设备正常。</p><table tabindex="0"><thead><tr><th>看到的质量</th><th>应怎样理解</th></tr></thead><tbody><tr><td>读取正常</td><td>仍要核对来源与时间是否符合本次检查目标</td></tr><tr><td>读取失败</td><td>保留错误，检查对应来源和连接，不当成有效零值</td></tr><tr><td>数据陈旧</td><td>值可能不是当前结果，先核对时间与来源状态</td></tr><tr><td>状态未知或配置预览</td><td>不能据此认定现场数据已读通</td></tr></tbody></table><p>页面提供 <strong>“设置默认值”</strong>。未连接运行态数据时，计算调试和页面预览可能使用这个开发态默认值。它不是设备当前值，也不能作为正式采集成功的证明。</p><p>确需设置时，打开“设置开发态默认值”，按数据类型填写；复杂值按页面要求使用合法 JSON。点击“保存”后核对详情；不再需要时使用“清除默认值”，再检查实际显示结果。</p><h2 id="_4-用标签整理" tabindex="-1">4. 用标签整理 <a class="header-anchor" href="#_4-用标签整理" aria-label="Permalink to &quot;4. 用标签整理&quot;">​</a></h2><p>单个数据点可通过列表的 <strong>“+ 标签”</strong>，或详情“标签”区域的 **“编辑”**打开管理面板。选择或输入需要的标签，点击 <strong>“保存”</strong>，刷新后再检查。</p><p>批量打标签时：</p><ol><li>先勾选目标，核对选中数量。</li><li>点击 <strong>“打标签”</strong>，填写要合并的标签。</li><li>保存并核对结果；已有标签会保留。</li></ol><p>“当前页”和“全部结果”范围不同，后者可能覆盖当前筛选的多页结果。批量操作前再次检查筛选和数量，不只看眼前几行。</p><h2 id="_5-谨慎处理失效数据点" tabindex="-1">5. 谨慎处理失效数据点 <a class="header-anchor" href="#_5-谨慎处理失效数据点" aria-label="Permalink to &quot;5. 谨慎处理失效数据点&quot;">​</a></h2><p>“失效”表示来源配置等关联已经失效，不等同于一次读取失败。这些项可保留用于核对，不需要看到失效就立即清理。</p><p>需要清理时，先查看详情和相关影响，再点击该行 <strong>“清理失效数据点”</strong>，核对确认框后点击 <strong>“清理”</strong>。操作不可恢复。</p><p>批量清理只处理失效项，但“全部结果”会扩大到当前筛选范围。确认前核对对象和数量，不把清理当成恢复连接的方法。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>返回<a href="/induframe-docs/zh/guide/datacenter.html">数据中心入门</a>选择下一项任务，或<a href="/induframe-docs/zh/guide/industrial-connections.html">配置工业采集连接</a>。检查页面取数见<a href="/induframe-docs/zh/guide/preview.html">预览工程页面</a>。</p><p>问题持续时，记录工程、数据点路径、来源、时间和页面提示交给维护人员，不提供密码或连接密钥。</p>',28)])])}const g=a(n,[["render",d]]);export{c as __pageData,g as default};
